@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));
@custom-variant theme-forest (&:is(.theme-forest *));

@theme {
  /* === Vela palette — cream (warm off-white base) === */
  --color-cream-50:  oklch(0.991 0.005 80);
  --color-cream-100: oklch(0.975 0.008 78);
  --color-cream-200: oklch(0.949 0.012 76);
  --color-cream-300: oklch(0.910 0.018 74);
  --color-cream-400: oklch(0.846 0.024 72);
  --color-cream-500: oklch(0.760 0.028 68);
  --color-cream-600: oklch(0.640 0.026 65);
  --color-cream-700: oklch(0.512 0.022 62);
  --color-cream-800: oklch(0.388 0.018 58);
  --color-cream-900: oklch(0.262 0.014 54);
  --color-cream-950: oklch(0.180 0.010 50);

  /* === Vela palette — forest (deep sage authority) === */
  --color-forest-50:  oklch(0.972 0.018 155);
  --color-forest-100: oklch(0.940 0.030 156);
  --color-forest-200: oklch(0.876 0.046 158);
  --color-forest-300: oklch(0.792 0.060 159);
  --color-forest-400: oklch(0.668 0.072 160);
  --color-forest-500: oklch(0.520 0.075 160);
  --color-forest-600: oklch(0.420 0.062 158);
  --color-forest-700: oklch(0.330 0.050 156);
  --color-forest-800: oklch(0.246 0.038 154);
  --color-forest-900: oklch(0.184 0.030 152);
  --color-forest-950: oklch(0.140 0.025 150);

  /* === Vela palette — amber (warm gold CTA) === */
  --color-amber-50:  oklch(0.985 0.018 80);
  --color-amber-100: oklch(0.955 0.038 78);
  --color-amber-200: oklch(0.910 0.062 75);
  --color-amber-300: oklch(0.852 0.085 70);
  --color-amber-400: oklch(0.770 0.100 62);
  --color-amber-500: oklch(0.682 0.105 60);
  --color-amber-600: oklch(0.580 0.098 56);
  --color-amber-700: oklch(0.470 0.082 52);
  --color-amber-800: oklch(0.362 0.062 48);
  --color-amber-900: oklch(0.252 0.044 44);
  --color-amber-950: oklch(0.168 0.028 42);

  /* === Vela palette — ink (warm neutral text) === */
  --color-ink-50:  oklch(0.988 0.004 60);
  --color-ink-100: oklch(0.962 0.005 58);
  --color-ink-200: oklch(0.910 0.005 56);
  --color-ink-300: oklch(0.838 0.005 54);
  --color-ink-400: oklch(0.696 0.005 52);
  --color-ink-500: oklch(0.560 0.005 50);
  --color-ink-600: oklch(0.434 0.005 48);
  --color-ink-700: oklch(0.330 0.005 45);
  --color-ink-800: oklch(0.232 0.005 42);
  --color-ink-900: oklch(0.165 0.006 40);
  --color-ink-950: oklch(0.110 0.006 38);

  /* === Typography === */
  --font-display: "Fraunces", ui-serif, Georgia, "Times New Roman", serif;
  --font-body: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: "Fraunces", ui-serif, Georgia, serif;

  /* === Radius (supplements lean tight) === */
  --radius-sm: 6px;
  --radius-md: 8px;
